import Foundation
enum TempoError: Error { case invalid }
final class Metronome {
    private let lock = NSLock()
    private var bpm = 60
    func set(_ value: Int) throws {
        lock.lock()
        guard value > 0 else { throw TempoError.invalid }
        bpm = value
        lock.unlock()
    }
    func read() -> Int {
        lock.lock(); defer { lock.unlock() }
        return bpm
    }
}

